import{_ as t,o as r,c as a,ag as n}from"./chunks/framework.DTisvaUJ.js";const p=JSON.parse('{"title":"Azure Translator setup","description":"Set up Azure Translator for cloud translation in Mutelink: create a resource, select the free tier and enter your key and region.","frontmatter":{"description":"Set up Azure Translator for cloud translation in Mutelink: create a resource, select the free tier and enter your key and region.","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/en/guide/azure-translator"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:title","content":"Azure Translator setup | Mutelink"}],["meta",{"property":"og:description","content":"Set up Azure Translator for cloud translation in Mutelink: create a resource, select the free tier and enter your key and region."}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/en/guide/azure-translator"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Azure Translator setup | Mutelink"}],["meta",{"name":"twitter:description","content":"Set up Azure Translator for cloud translation in Mutelink: create a resource, select the free tier and enter your key and region."}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/guide/azure-translator"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/guide/azure-translator"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/guide/azure-translator"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/guide/azure-translator"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/guide/azure-translator"}]]},"headers":[],"relativePath":"en/guide/azure-translator.md","filePath":"en/guide/azure-translator.md"}'),o={name:"en/guide/azure-translator.md"};function i(s,e,l,u,c,h){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="azure-translatorの導入" tabindex="-1">Azure Translator setup <a class="header-anchor" href="#azure-translatorの導入" aria-label="Permalink to &quot;Azure Translator setup {#azure-translatorの導入}&quot;">​</a></h1><p>Create a key to use Azure Translator, Microsoft’s cloud translation service, in Mutelink. The F0 tier includes up to 2 million characters per month for free.</p><p>Local translation with PLaMo or TranslateGemma does not require this setup. See <a href="/Mutelink-releases/en/compare/translation">translation engines</a> to choose an engine.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>Azure registration requires an address, phone number and credit-card verification. Complete registration and verification for a <strong>pay-as-you-go subscription</strong>. Simply creating a Microsoft account is not enough.</li><li>With the F0 free tier, exceeding 2 million characters does not incur charges; translation stops for the rest of that month.</li><li>Text is sent to Microsoft’s servers (<a href="/Mutelink-releases/en/about/privacy">Privacy</a>).</li><li>Azure portal screens and wording may change. If they differ from this guide, look for similarly named options.</li></ul></div><h2 id="_1-azureの従量課金制サブスクリプションを用意する" tabindex="-1">1. Prepare an Azure pay-as-you-go subscription <a class="header-anchor" href="#_1-azureの従量課金制サブスクリプションを用意する" aria-label="Permalink to &quot;1. Prepare an Azure pay-as-you-go subscription {#_1-azureの従量課金制サブスクリプションを用意する}&quot;">​</a></h2><ol><li>Open the <a href="https://azure.microsoft.com/ja-jp/pricing/purchase-options/azure-account" target="_blank" rel="noreferrer">Azure account registration page</a> and start pay-as-you-go registration.</li><li>Sign in with a Microsoft account, or create one.</li><li>Enter your address and other registration details, verify your phone number and credit card, and register a payment method.</li><li>Under Subscriptions in the <a href="https://portal.azure.com/" target="_blank" rel="noreferrer">Azure portal</a>, confirm that your pay-as-you-go subscription exists and is active.</li><li>If you started with a free account, use Upgrade to switch to pay-as-you-go when required.</li></ol><p>Skip this step if you already have an active pay-as-you-go subscription.</p><p>The subscription’s pay-as-you-go status and the Translator resource’s pricing tier are separate settings. Choose <strong>Free F0</strong> for Translator below. Creating other paid services or selecting a paid Translator tier will incur usage charges.</p><h2 id="_2-translatorのリソースを作る" tabindex="-1">2. Create a Translator resource <a class="header-anchor" href="#_2-translatorのリソースを作る" aria-label="Permalink to &quot;2. Create a Translator resource {#_2-translatorのリソースを作る}&quot;">​</a></h2><ol><li>Open the <a href="https://portal.azure.com/" target="_blank" rel="noreferrer">Azure portal</a>.</li><li>Search for “Translator,” select it (called 翻訳ツール in the Japanese UI), and click Create.</li><li>Enter the following settings.</li></ol><table tabindex="0"><thead><tr><th>Setting</th><th>Value</th></tr></thead><tbody><tr><td>Subscription</td><td>Your subscription; keep the selected value if you have only one</td></tr><tr><td>Resource group</td><td>Click Create new and choose a name, such as <code>mutelink</code></td></tr><tr><td>Region</td><td>A nearby region, such as <code>Japan East</code>. <strong>Enter this same region in Mutelink later.</strong></td></tr><tr><td>Name</td><td>An identifying name, such as <code>mutelink-translator-1234</code>. If already taken, change the ending digits.</td></tr><tr><td>Pricing tier</td><td><strong>Free F0</strong> (2 million characters per month free)</td></tr></tbody></table><ol start="4"><li>Click Review + create, check the settings, then click Create.</li><li>When deployment is complete, click Go to resource.</li></ol><p>Go to resource may open the resource group instead of Translator. Select your Translator in its list. If it is missing immediately after creation, click Refresh and then click its name when it appears.</p><div class="tip custom-block"><p class="custom-block-title">If Free F0 is unavailable</p><p>Only one free-tier Translator resource is allowed per subscription. Check whether a previous resource still exists.</p></div><h2 id="_3-キーとリージョンを確認する" tabindex="-1">3. Find your key and region <a class="header-anchor" href="#_3-キーとリージョンを確認する" aria-label="Permalink to &quot;3. Find your key and region {#_3-キーとリージョンを確認する}&quot;">​</a></h2><ol><li>Open your Translator and select Keys and Endpoint in the left menu. If you are in the resource group, open Translator from the list first.</li><li>Copy KEY 1.</li><li>Note the Location/Region value, such as <code>japaneast</code>.</li></ol><div class="warning custom-block"><p class="custom-block-title">Keep your key private</p><p>Anyone with your key can use your translation quota. Keep it out of streams, screen sharing and screenshots. If leaked, regenerate KEY 1 on this same page.</p></div><h2 id="_4-mutelinkに入れる" tabindex="-1">4. Enter it in Mutelink <a class="header-anchor" href="#_4-mutelinkに入れる" aria-label="Permalink to &quot;4. Enter it in Mutelink {#_4-mutelinkに入れる}&quot;">​</a></h2><ol><li>Open Mutelink Settings &gt; Translation.</li><li>Under Azure Translator, enter KEY 1 in Azure Translator key and the saved region string, such as <code>japaneast</code>, in Region.</li><li>Run the translation test and confirm that a translation is returned.</li><li>Place Azure Translator at your preferred position in the engine priority list.</li></ol><p>The key is saved only in settings on this PC.</p><h2 id="うまくいかないとき" tabindex="-1">Troubleshooting <a class="header-anchor" href="#うまくいかないとき" aria-label="Permalink to &quot;Troubleshooting {#うまくいかないとき}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to check</th></tr></thead><tbody><tr><td>Test reports an invalid key</td><td>Check for surrounding spaces and make sure this is a Translator key, not another resource’s key</td></tr><tr><td>Test reports a region error</td><td>Enter the exact Location/Region string: <code>japaneast</code>, not <code>Japan East</code></td></tr><tr><td>Translation suddenly stops</td><td>Check whether the monthly 2-million-character quota is exhausted in the resource’s Metrics in Azure</td></tr><tr><td>Fails just after creation</td><td>A new resource may take several minutes to become usable</td></tr></tbody></table><p>Mutelink Settings &gt; Translation shows this app’s character counts on this PC for this month, today and the last 30 days. Usage of the same key elsewhere is not included.</p><h2 id="やめるとき" tabindex="-1">When you stop using Azure <a class="header-anchor" href="#やめるとき" aria-label="Permalink to &quot;When you stop using Azure {#やめるとき}&quot;">​</a></h2><p>Delete the resource, or its resource group, in Azure. Clear the key field in Mutelink Settings &gt; Translation too.</p><p>For registration and pricing details, see Microsoft’s <a href="https://azure.microsoft.com/ja-jp/pricing/purchase-options/azure-account" target="_blank" rel="noreferrer">Azure account guide</a> and <a href="https://learn.microsoft.com/ja-jp/azure/ai-services/translator/how-to/create-translator-resource" target="_blank" rel="noreferrer">Translator resource instructions</a>.</p>',26)])])}const g=t(o,[["render",i]]);export{p as __pageData,g as default};
